function config(){return {sourceFiles,sources:$('sources').value,yaml:$('yaml').value,directCN:$('directCN').checked,fallback:$('fallback').value,rules:Array.from($('rules').children,r=>({type:r.children[0].value,value:r.children[1].value,target:r.children[2].value}))};}
function populate(c){sourceFiles=c.sourceFiles||{};$('sources').value=c.sources||'';$('yaml').value=c.yaml||'';$('directCN').checked=c.directCN!==false;$('fallback').value=c.fallback||'\u8282\u70B9\u9009\u62E9';$('rules').replaceChildren();(c.rules||[]).forEach(rule);$('noRules').hidden=!!c.rules?.length;renderFiles();}
function display(r){last=r;targets=r.targets;$('count').textContent=r.count;$('output').textContent=JSON.stringify(r.config,null,2);$('reports').replaceChildren();for(const item of r.reports){const line=document.createElement('div');line.className='report'+(item.warning?' warning':'');line.textContent=item.name+' \xB7 '+item.count+' \u4E2A\u8282\u70B9'+(item.warning?' \xB7 '+item.warning:'');$('reports').append(line);}for(const row of $('rules').children){const select=row.children[2],current=select.value;select.replaceChildren();[...new Set([...targets,current])].forEach(t=>option(select,t));select.value=current;}}
