function renderGroups(){const body=$('defaultGroups');body.replaceChildren();for(const g of defaultGroups){const row=document.createElement('tr');const target=g.name==='\u6F0F\u7F51\u4E4B\u9C7C'?$('fallback').value:g.default;for(const text of [g.name,target==='DIRECT'?'\u76F4\u8FDE \xB7 DIRECT':target,g.description]){const cell=document.createElement('td');cell.style.cssText='padding:10px 12px 10px 0;border-bottom:1px solid var(--line)';cell.textContent=text;row.append(cell);}body.append(row);}}
async function load(){const data=await api('config');targets=data.targets||targets;defaultGroups=data.defaultGroups||[];populate(data.config);renderGroups();$('subscription').value=data.subscription;$('login').hidden=true;$('app').hidden=false;dirty=false;}
$('fallback').addEventListener('change',renderGroups);
$('loginForm').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('login',{key:$('key').value});$('key').value='';await load();$('status').hidden=true;});};
