$('save').onclick=()=>run($('save'),async()=>{message('\u6B63\u5728\u6821\u9A8C\u5E76\u4FDD\u5B58\u2026');const r=await api('config',config());display(r);dirty=false;message('\u914D\u7F6E\u5DF2\u4FDD\u5B58\u3002\u8BF7\u5728\u5BA2\u6237\u7AEF\u66F4\u65B0\u8BA2\u9605\uFF1B\u8DE8\u5730\u533A\u540C\u6B65\u53EF\u80FD\u9700\u8981\u7EA6\u4E00\u5206\u949F\u3002');});
$('copy').onclick=()=>run($('copy'),async()=>{await navigator.clipboard.writeText($('subscription').value);message('\u8BA2\u9605\u5730\u5740\u5DF2\u590D\u5236'+(dirty?'\u3002\u6CE8\u610F\uFF1A\u5F53\u524D\u4FEE\u6539\u5C1A\u672A\u4FDD\u5B58\u3002':'\u3002'));});
